namespace {
size_t rig_checks=0;
void demand(bool b,const char*s){if(!b)throw std::runtime_error(s);++rig_checks;std::cout<<"PASS "<<s<<std::endl;}
bool denied(auto call){try{call();return false;}catch(const std::exception&e){std::cout<<"expected refusal "<<e.what()<<std::endl;return true;}}
void ready(Document&d){demand(d.wait_asset(std::chrono::seconds(120))&&d.wait_mesh(std::chrono::seconds(120))&&d.frame().state->error.empty(),"Actual authoring worker and current immutable mesh settle without error");}
void ink(Scene&s){auto&p=*s.active().painted;Brush b;b.from=b.to={0,0,0};b.normal={0,0,1};b.radius=.075f;b.strength=.7f;PaintSettings settings;settings.front_only=false;settings.color={.2f,.7f,.4f,.43f};p.add_layer("Retained brush detail");p.begin_stroke();p.stamp(b,settings);demand(p.end_stroke(),"Actual painted RGBA detail precedes rigging");settings.channel=PaintChannel::Roughness;settings.roughness=.23f;p.begin_stroke();p.stamp(b,settings);demand(p.end_stroke(),"Actual PBR detail precedes rigging");p.layer_properties("Retained brush detail",true,.67f);}
Scene native_case(bool existing){Scene s;auto mesh=mirrored_fan();s.active().painted=std::make_shared<PaintedMesh>(mesh,64);s.active().mesh_active=true;ink(s);auto&o=s.active();Mesh target;std::vector<uint32_t>map;for(auto v:mesh.indices){map.push_back(v);target.positions.push_back(mesh.positions[v]);target.normals.push_back(mesh.normals[v]);target.uv.push_back({.5f-.7f*(mesh.uv[v][1]-.5f),.5f+.7f*(mesh.uv[v][0]-.5f)});target.indices.push_back(uint32_t(target.indices.size()));}auto kept=detail::retain_native_paint(o,target,map);o.painted=std::move(kept.paint);o.material_bindings=detail::bind_native_paint(kept.owner,{});
 if(existing){DeformationState d(target);d.skeleton=Skeleton{{{"base",-1,{},.2f},{"tip",0,{{0,.025f,0}},.1f}}};d.skin=SkinWeights{};for(size_t v=0;v<target.positions.size();++v)d.skin->vertices.push_back({{0,.8f},{1,.2f}});s.set_deformation(o.id,d);}s.validate();return s;}
Scene canonical_case(bool existing,bool uv,bool clear){auto s=baked_fan(existing,true,true);ink(s);Document d;d.replace(s);ready(d);d.convert_baked_normals();ready(d);s=d.copy_scene();
 if(uv){auto&o=s.active();SourceUvBakeInput in;in.paint=o.painted;in.current_material=o.material_bindings;in.current_deformation=o.deformation;for(auto v:o.painted->mesh().indices){const auto&m=o.painted->mesh();in.source_vertices.push_back(v);in.target.positions.push_back(m.positions[v]);in.target.normals.push_back(m.normals[v]);in.target.uv.push_back({.5f-.8f*(m.uv[v][1]-.5f),.5f+.8f*(m.uv[v][0]-.5f)});in.target.indices.push_back(uint32_t(in.target.indices.size()));}auto out=adopt_source_uv_bake(bake_source_uv(in));o.painted=std::move(out.paint);o.material_bindings=std::move(out.material_bindings);o.deformation=std::move(out.deformation);}
 if(clear){Document c;c.replace(s);ready(c);c.clear_bake();ready(c);s=c.copy_scene();demand(!s.active().painted->baked()&&s.active().material_bindings->canonical_attributes,"Actual Clear removes active normal field while retaining genuine canonical history");}s.validate();return s;}
struct Input{Scene scene;uint64_t target=0,reference=0;SkinAuthoringOptions options;};
Input with_reference(Scene s){Input out;out.target=s.active().id;const auto target=s.active();out.reference=s.add("Explicit current native weight reference",Volume{});auto&r=s.object(out.reference);r.mesh_active=true;r.visible=false;r.group=target.group;r.transform=target.transform;r.affine_edit=target.affine_edit;r.painted=std::make_shared<PaintedMesh>(target.painted->mesh(),64);auto d=target.deformation?*target.deformation:DeformationState(r.painted->mesh());if(!d.skeleton)d.skeleton=Skeleton{{{"base",-1,{},.2f},{"tip",0,{{0,.025f,0}},.1f}}};d.skin=SkinWeights{};for(size_t i=0;i<r.painted->mesh().positions.size();++i)d.skin->vertices.push_back({{0,.125f},{1,.875f}});d.validate(r.painted->mesh());r.deformation=std::make_shared<const DeformationState>(d);s.select(out.target);s.validate();out.scene=std::move(s);out.options.mode=SkinAuthoringMode::Transfer;out.options.reference=out.reference;out.options.transfer_distance=10;return out;}
void same_paint(const SculptObject&a,const SculptObject&b){demand(a.material_bindings==b.material_bindings&&a.painted->mesh_owner()==b.painted->mesh_owner()&&detail::NativeWeightPaintAccess::same_current(*a.painted,*b.painted)&&a.appearance==b.appearance&&a.shape_source==b.shape_source&&a.bake_recipe==b.bake_recipe,"Rigging retains exact current paint/UV/normal/shape/recipe authorities and editable values");}
}
#ifndef DOME_RIG_AFTER_AUTHORING_HELPERS_ONLY
int main(int argc,char**argv)try{if(argc!=2)return 2;const std::filesystem::path root=argv[1];std::filesystem::create_directories(root);
 for(unsigned kind=0;kind<6;++kind){std::cout<<"CASE "<<kind<<std::endl;const auto out=root/std::to_string(kind);std::filesystem::create_directories(out);setenv("XDG_STATE_HOME",(out/"state").c_str(),1);setenv("XDG_CONFIG_HOME",(out/"config").c_str(),1);
  auto in=with_reference(kind==0?native_case(false):kind==5?native_case(true):canonical_case(kind>=3,kind>=3,kind==2||kind==4));const auto before=in.scene.encode();const auto&target=in.scene.object(in.target);auto bound=in.scene;size_t polls=0;demand(author_skin(bound,in.target,in.options,[&]{++polls;return false;}),"Actual ordinary transfer changes native recipient skin");const auto first=bound.object(in.target).rig_source;
  demand(first&&first->deformation==target.deformation&&first->material_bindings==target.material_bindings&&first->shape_source==target.shape_source&&first->bake_recipe==target.bake_recipe&&first->paint->mesh_owner()==target.painted->mesh_owner(),"Changed ordinary binding captures a complete genuine first original source");same_paint(bound.object(in.target),target);auto retained=bound;retained.object(in.target).deformation=target.deformation;retained.object(in.target).rig_source=target.rig_source;demand(retained.encode()==before,"Every unrelated source/group and all other target fields remain exact in complete context");bound.validate();demand(in.scene.encode()==before,"Detached complete original source remains unchanged");
  auto same=bound;const auto exact=bound.encode();demand(!author_skin(same,in.target,in.options)&&same.encode()==exact&&same.object(in.target).rig_source==first,"Identical current binding is a true no-op and retains the first capsule");
  for(size_t at:std::set<size_t>{1,std::max(size_t(1),polls/2),std::max(size_t(1),polls-1),polls}){auto cancelled=in.scene;size_t count=0;demand(denied([&]{author_skin(cancelled,in.target,in.options,[&]{return ++count>=at;});})&&cancelled.encode()==before&&!cancelled.object(in.target).rig_source,"Actual early/late bind cancellation preserves source and publishes no capsule");}
  auto changed=bound;auto d=std::make_shared<DeformationState>(*changed.object(in.reference).deformation);for(auto&row:d->skin->vertices)row={{0,.75f},{1,.25f}};changed.object(in.reference).deformation=d;const auto other=changed.object(in.reference).deformation;demand(author_skin(changed,in.target,in.options)&&changed.object(in.target).rig_source==first&&changed.object(in.reference).deformation==other,"Actual changed existing-rig rebind preserves first source and read-only reference");
  auto restored=bound;restore_rig_source(restored,in.target,false);demand(restored.encode()==before,"Complete rig Restore recovers exact authored pre-bind paint/UV/normal and native state");
  Document doc;doc.replace(in.scene);ready(doc);doc.bind_skin(in.options);doc.save_async(out/"bound.dsculpt").get();ready(doc);demand(doc.copy_scene().encode()==exact&&Scene::load(out/"bound.dsculpt").encode()==exact,"Actual native worker and immediate accepted Save retain exact complete bound scene");
  demand(doc.undo()&&doc.copy_scene().encode()==before&&!doc.frame().state->can_undo&&doc.redo()&&doc.copy_scene().encode()==exact,"Changed bind owns exactly one recoverable Undo/Redo");
  doc.bind_skin(in.options);doc.save_async(out/"noop.dsculpt").get();ready(doc);demand(doc.copy_scene().encode()==exact&&doc.undo()&&doc.copy_scene().encode()==before&&!doc.frame().state->can_undo&&doc.redo(),"Actual no-op bind creates no extra history entry");
  auto posed=doc.copy_scene();RigEdit pose;pose.linked_pose=false;pose.joint=JointAdjustment{1,{0,0,25},{}};edit_rig(posed,in.target,pose);doc.edit_scene("Pose bound authored object",[=](Scene&s,const auto&cancel){edit_rig(s,in.target,pose,cancel);});doc.save_async(out/"posed.dsculpt").get();ready(doc);demand(doc.copy_scene().encode()==posed.encode(),"Actual new native pose retains independently computed deformation and source");same_paint(doc.copy_scene().object(in.target),target);
  doc.edit_scene("Restore complete authored source",[=](Scene&s,const auto&cancel){restore_rig_source(s,in.target,false,cancel);});doc.save_async(out/"restored.dsculpt").get();ready(doc);demand(doc.copy_scene().encode()==before&&Scene::load(out/"restored.dsculpt").encode()==before&&doc.undo()&&doc.copy_scene().encode()==posed.encode()&&doc.redo()&&doc.copy_scene().encode()==before,"Actual Restore/ordered Save/Undo/Redo recovers complete original authored state");
 }
 std::cout<<"PASS rig_after_authoring_checks="<<rig_checks<<std::endl;return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}

#endif
